const { Writable } = require('stream');
const sink = new Writable({
  highWaterMark: 4,
  write(chunk, enc, cb) { setImmediate(() => cb()); }
});
let backpressure = 0;
const total = 10;
for (let i = 0; i < total; i++) {
  const ok = sink.write(Buffer.from('x'));
  if (!ok) backpressure++;
}
sink.end(() => {
  console.log('writes=' + total);
  console.log('backpressureTriggered=' + backpressure);
  console.log('backpressureHappened=' + (backpressure > 0));
});
